import { useState, useRef, useEffect } from 'react';
import { airports } from '../components/FlightSearch/data/airports';

export function useHybridPathInput() {
  const [path, setPath] = useState('');
  const [currentInput, setCurrentInput] = useState('');
  const [showAirportSelect, setShowAirportSelect] = useState(false);
  const inputRef = useRef(null);

  // Convert airports data to select options with simpler format
  const airportOptions = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name}`
  }));

  // Filter airports based on current input
  const filteredAirports = airportOptions.filter(option => {
    const searchStr = currentInput.toLowerCase();
    return (
      option.value.toLowerCase().includes(searchStr) ||
      option.label.toLowerCase().includes(searchStr)
    );
  });

  // Handle input changes
  const handleInputChange = (value) => {
    setCurrentInput(value);
    
    // Get the last segment of the path
    const segments = path.split('-');
    const lastSegment = segments[segments.length - 1];
    
    // If the last character is not '/' or '-', show airport selection
    const lastChar = lastSegment.slice(-1);
    if (lastChar && lastChar !== '/' && lastChar !== '-') {
      setShowAirportSelect(true);
    } else {
      setShowAirportSelect(false);
    }
  };

  // Handle airport selection
  const handleAirportSelect = (value) => {
    if (!value) return;

    const segments = path.split('-');
    const lastSegment = segments[segments.length - 1];
    const newLastSegment = lastSegment.slice(0, -currentInput.length) + value;
    
    segments[segments.length - 1] = newLastSegment;
    const newPath = segments.join('-');
    
    setPath(newPath);
    setShowAirportSelect(false);
    setCurrentInput('');
  };

  // Handle key down events
  const handleKeyDown = (e) => {
    if (e.key === 'Escape') {
      setShowAirportSelect(false);
    }
    if (e.key === 'Enter' && showAirportSelect && filteredAirports.length > 0) {
      handleAirportSelect(filteredAirports[0].value);
    }
  };

  // Focus input on mount
  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, []);

  return {
    path,
    currentInput,
    showAirportSelect,
    inputRef,
    airportOptions: filteredAirports,
    handleInputChange,
    handleAirportSelect,
    handleKeyDown,
    setPath
  };
}
